,`jenis_izin` enum('sakit','izin','urusan_keluarga','keperluan_pribadi','lainnya','kelas')
,`alasan` text
,`bukti_pendukung` varchar(255)
,`status` enum('pending','disetujui','ditolak')
,`keterangan_guru` text
,`tanggal_pengajuan` timestamp
